export const filmHeadingSizes=[36,36,28,22,14];
export const filmHeadingColors=['262626','404040','595959','7F7F7F','7F7F7F'];
const base=import.meta.env.BASE_URL+'fonts/';
export const filmTypographyCss=`@font-face{font-family:"LM Mono Light 10";src:url("${base}lmmonolt10-regular.otf") format("opentype");font-weight:400;font-style:normal}${['Regular','Bold','Italic','BoldItalic'].map((name)=>`@font-face{font-family:"Courier Prime";src:url("${base}CourierPrime-${name}.ttf") format("truetype");font-weight:${name.includes('Bold')?700:400};font-style:${name.includes('Italic')?'italic':'normal'}}`).join('')}
.book-page{color:#000;font-family:"LM Mono Light 10","Courier New",monospace!important;font-size:12pt!important;line-height:1.35!important}.book-page .book-content{ text-align:justify }
${filmHeadingSizes.map((size,i)=>`.book-page h${i+1}{font-family:"Courier Prime","Courier New",monospace!important;font-size:${size}pt!important;font-weight:700;text-align:center;color:#${filmHeadingColors[i]};font-variant:${[0,1,3].includes(i)?'small-caps':'normal'};text-transform:${i===2?'uppercase':'none'}!important;font-style:${i===3?'italic':'normal'};line-height:1.15;margin:${[12,11.35,8.5,6,6][i]}pt 0 ${[6,8.5,8.5,6,3][i]}pt;}`).join('')}
.book-page.title-page .book-content :is(h1,h2,h3,h4,h5){color:#fff}.book-page[data-frontmatter] .book-content,.book-page[data-frontmatter] .book-content :is(h1,h2,h3,h4,h5){color:#fff;text-shadow:0 1px 3px #000}.book-page[data-frontmatter] .book-number{color:#fff!important}.book-page[data-frontmatter] .book-content{font-weight:700;font-family:"LM Mono Light 10","Courier New",monospace;font-size:14pt;line-height:1.35}.book-page[data-frontmatter] .book-content :is(h1,h2){font-family:"Courier Prime",monospace!important;font-size:36pt!important;font-variant:normal;text-transform:none!important}.book-page[data-frontmatter] .book-content h3{font-family:"Courier Prime",monospace!important;font-size:18pt!important;font-variant:normal;text-transform:none!important}.book-page[data-frontmatter="credits"] .book-content{font-size:12pt}.book-page[data-frontmatter="credits"] .book-content>p:nth-of-type(-n+2){font-family:"Courier Prime",monospace;font-size:18pt}.book-object-locked:hover{outline:none!important}.book-page[data-generated] .book-content p{font-size:12pt;line-height:1.35;text-align:left;margin-bottom:7pt}`;
export const filmWordStyles=()=>`<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="LM Mono Light 10" w:hAnsi="LM Mono Light 10"/><w:sz w:val="24"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:line="324" w:lineRule="auto"/><w:jc w:val="both"/></w:pPr></w:pPrDefault></w:docDefaults>${filmHeadingSizes.map((size,i)=>`<w:style w:type="paragraph" w:styleId="Heading${i+1}"><w:name w:val="heading ${i+1}"/><w:pPr><w:keepNext/><w:spacing w:line="276" w:lineRule="auto"/><w:jc w:val="center"/><w:outlineLvl w:val="${i}"/></w:pPr><w:rPr><w:rFonts w:ascii="Courier Prime" w:hAnsi="Courier Prime"/><w:b/>${[0,1,3].includes(i)?'<w:smallCaps/>':''}${i===2?'<w:caps/>':''}${i===3?'<w:i/>':''}<w:color w:val="${filmHeadingColors[i]}"/><w:sz w:val="${size*2}"/></w:rPr></w:style>`).join('')}</w:styles>`;
